import React, { useEffect, useState, useRef } from "react";
import api from "../api";
import io from "socket.io-client";

type Ticket = {
  _id: string;
  title: string;
  description?: string;
  status: "open" | "in_progress" | "closed";
  category: "billing" | "technical" | "general";
  priority: "low" | "medium" | "high";
  createdBy: any;
  assignee: any;
};

interface InternalDashboardProps {
  name: string;
}

const InternalDashboard: React.FC<InternalDashboardProps> = ({ name }) => {
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const socketRef = useRef<any>(null);

  useEffect(() => {
    socketRef.current = io("http://localhost:5050", {
      transports: ["websocket"],
      withCredentials: true,
    } as any);

    return () => {
      socketRef.current?.disconnect();
    };
  }, []);

  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      setTickets(res.data);
    } catch (err) {}
  };

  useEffect(() => {
    fetchTickets();

    socketRef.current?.on("ticketUpdated", fetchTickets);
    socketRef.current?.on("ticketCreated", fetchTickets);

    return () => {
      socketRef.current?.off("ticketUpdated");
      socketRef.current?.off("ticketCreated");
    };
  }, []);

  return (
    <div>
      <h1>Internal Dashboard</h1>
      <p>Welcome, {name}!</p>

      <h2>Assigned Tickets</h2>
      <ul>
        {tickets.map((t) => (
          <li key={t._id}>
            <strong>{t.title}</strong> — {t.status}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default InternalDashboard;
